/**
 * Converts normal text to Leet Speak
 * @param text - The text to convert to Leet Speak
 * @returns The text converted to Leet Speak
 */
export function leetSpeakEncode(text: string): string;

/**
 * Converts Leet Speak back to normal text
 * @param leetText - The Leet Speak text to convert back
 * @returns The decoded normal text
 */
export function leetSpeakDecode(leetText: string): string;
